<?php
require_once __DIR__.'/app/lib/Db.php';
require_once __DIR__.'/app/lib/VendorPortfolio.php';
$path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';
if(!preg_match('#^/vendors/([a-z0-9-]+)/?$#',$path,$m)){http_response_code(404);exit('Not found');}
try{$vendor=VendorPortfolio::vendorProfile(Db::pdo(),$m[1]);}catch(Throwable $e){$vendor=null;}
if(!$vendor){http_response_code(404);exit('Vendor not found');}
$esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
$territoryText=static function(array $rows) use($esc){if(!$rows)return 'Territory not specified';return implode(' · ',array_map(fn($t)=>$esc($t['territory_name']??$t['territory_code']??''),$rows));};
$renderProducts=static function(array $rows) use($esc,$territoryText){if(!$rows)return '<p class="empty">No approved relationships published yet.</p>';$html='<div class="grid">';foreach($rows as $r){$html.='<article class="card"><div class="rel">'.$esc($r['relationship_label']).'</div><h3><a href="/software/'.$esc($r['product_slug']).'">'.$esc($r['product_name']).'</a></h3>';if(!empty($r['category_name']))$html.='<div class="meta">'.$esc($r['category_name']).'</div>';if(!empty($r['short_description']))$html.='<p>'.$esc($r['short_description']).'</p>';$html.='<div class="meta">Territory: '.$territoryText($r['territories']).' · Relationship '.$esc($r['verification_status']).'</div>';if(!empty($r['evidence_source_url']))$html.='<a class="evidence" href="'.$esc($r['evidence_source_url']).'" rel="nofollow noopener" target="_blank">Relationship evidence</a>';$html.='</article>';}$html.='</div>';return $html;};
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $esc($vendor['name']) ?> | TechSelectAI Vendor Profile</title><meta name="description" content="Verified software ownership and partner relationships for <?= $esc($vendor['name']) ?> on TechSelectAI."><link rel="icon" href="/favicon.svg"><style>body{font-family:Inter,Arial,sans-serif;margin:0;background:#f6f9fb;color:#24364b}.wrap{max-width:1080px;margin:auto;padding:36px 20px 60px}.brand img{height:36px}.hero{margin-top:30px;padding:28px;background:#fff;border:1px solid #dce7ee;border-radius:18px}.eyebrow,.rel{font-size:12px;font-weight:800;text-transform:uppercase;letter-spacing:.08em;color:#0f766e}.hero h1{margin:8px 0}.meta{font-size:12px;color:#64748b;line-height:1.5}.badge{display:inline-block;margin-top:10px;padding:6px 9px;border-radius:999px;background:#eef8f7;font-size:12px;font-weight:750}.section{margin-top:28px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:14px}.card{background:#fff;border:1px solid #e0e8ef;border-radius:14px;padding:18px}.card h3{margin:6px 0}.card p{color:#536174;line-height:1.55}.card a{color:#123b67}.evidence{display:inline-block;margin-top:10px;font-size:12px}.empty{padding:16px;border:1px dashed #cbd5e1;border-radius:12px;background:#fff;color:#64748b}.note{margin-top:30px;font-size:12px;color:#64748b;line-height:1.6}</style></head><body><div class="wrap"><a class="brand" href="/"><img src="/techselectai-logo.svg" alt="TechSelectAI"></a><section class="hero" id="overview" data-citation-section="overview"><div class="eyebrow">Vendor / company profile</div><h1><?= $esc($vendor['name']) ?></h1><?php if(!empty($vendor['description'])):?><p><?= $esc($vendor['description']) ?></p><?php endif;?><div class="meta"><?= !empty($vendor['headquarters_country_code'])?'HQ: '.$esc($vendor['headquarters_country_code']).' · ':'' ?><?= !empty($vendor['company_type'])?$esc($vendor['company_type']).' · ':'' ?>Profile status: <?= $esc($vendor['verification_status']) ?></div><span class="badge">Ownership and commercial representation are shown separately</span><?php if(!empty($vendor['website_url'])):?><p><a href="<?= $esc($vendor['website_url']) ?>" target="_blank" rel="nofollow noopener">Official website</a></p><?php endif;?></section><section class="section" id="owned-products" data-citation-section="owned-products"><h2>Owned / developed software</h2><?= $renderProducts($vendor['owned_products']) ?></section><section class="section" id="partner-products" data-citation-section="partner-products"><h2>Represented / partner software</h2><?= $renderProducts($vendor['partner_products']) ?></section><p class="note">TechSelectAI keeps software ownership separate from reseller, distributor, implementation-partner, referral and local-agent relationships. Partner relationships are displayed only after approval; verification status and territory remain visible and do not influence TechSelectAI recommendation ranking.</p></div></body></html>